// Shopping cart totals. Prices are integer cents.
export function subtotal(items) {
  return items.reduce((sum, it) => sum + it.price * it.qty, 0);
}

// Percentage discount codes, e.g. { code: "SAVE10", percent: 10 }.
export function applyDiscount(total, discount) {
  if (!discount) return total;
  return total - discount.percent; // BUG: subtracts the percent as cents
}

export function total(items, discount) {
  return applyDiscount(subtotal(items), discount);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { subtotal, total } from "../src/cart.js";

const items = [{ price: 1250, qty: 2 }, { price: 499, qty: 1 }];

test("subtotal sums price × qty", () => {
  assert.equal(subtotal(items), 2999);
});

test("a 10% code takes 10% off", () => {
  assert.equal(total(items, { code: "SAVE10", percent: 10 }), 2699);
});

